/**
 * 🔄 Auto-Sync Worker
 * - 로컬 폴더 스캔 (5분 간격)
 * - Notion 동기화 (1일 3회: 08:00, 16:00, 00:00)
 */

const fs = require('fs');
const path = require('path');
const sqlite3 = require('sqlite3').verbose();
const { Client } = require('@notionhq/client');
const { execFile } = require('child_process');

// 설정
const PROJECTS_BASE = '/home/kimjin/kim/Desktop/kim';
const CATEGORY_DIRS = [
  '01_Active_Projects',
  '02_Infrastructure',
  '03_Completed_Projects',
  '04_In_Progress_Projects',
  '05_Tools_Utilities',
  '06_Libraries_Packages',
  '07_Documentation',
  '08_Archive_Backup',
  'AION',
  'FREELANG_Projects',
  'code2'
];
const DB_PATH = path.join(process.env.HOME, 'kim/kim-projects.db');
const NOTION_DB_ID = '37cb2a51-8b32-46c5-b868-178da969b7ed';
const ENV_FILE = path.join(process.env.HOME, 'kim/.env');

// SQLite DB 연결
const db = new sqlite3.Database(DB_PATH, (err) => {
  if (err) {
    console.error('❌ DB 연결 실패:', err.message);
    process.exit(1);
  }
});

let notion = null;
let lastScanTime = null;

// Notion 클라이언트 초기화
function initNotion() {
  try {
    const env = fs.readFileSync(ENV_FILE, 'utf-8');
    const tokenMatch = env.match(/NOTION_TOKEN=([^\n]+)/);
    const notionToken = tokenMatch ? tokenMatch[1].trim() : null;

    if (notionToken && notionToken !== 'dummy_will_update_later') {
      notion = new Client({ auth: notionToken });
      console.log('✅ Notion API 초기화 완료');
    } else {
      console.warn('⚠️ Notion 토큰 없음 (dummy 토큰)');
    }
  } catch (err) {
    console.error('❌ Notion 초기화 실패:', err.message);
  }
}

// SQLite 유틸
function dbRun(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function(err) {
      if (err) reject(err);
      else resolve({ lastID: this.lastID, changes: this.changes });
    });
  });
}

function dbGet(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

